    public List<AppIndex.App> apps=Collections.emptyList();public boolean indexed;public final ExecutorService worker=Executors.newSingleThreadExecutor();public final Handler main=new Handler(Looper.getMainLooper());private LinearLayout root,nav,header,body;private ScrollView scroll;private Dialog gate;private Consumer<Boolean> permissionCb;private boolean redrawQueued;private int y;private String exportJson;
    @Override protected void onCreate(Bundle b){super.onCreate(b);db=((NexusApp)getApplication()).store;k=new Kit(this);vault=new KeyVault(this);tools=new ToolBox();gemini=new Gemini(db,vault);agent=new Agent(this,db,tools,gemini);voice=new Voice(this,this);screens=new Console(this);controls=new Controls(this);if(b!=null)tab=b.getString("page","home");locale();structure();render(false);index();}
